// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListBodyWeights The user's weight and body fat history, newest first.
	// (GET /body-weights)
	ListBodyWeights(ctx context.Context, request ListBodyWeightsRequestObject) (ListBodyWeightsResponseObject, error)
	// SaveBodyWeight Log the weight (and body fat) of a day, replacing the one logged for that day before.
	// (PUT /body-weights)
	SaveBodyWeight(ctx context.Context, request SaveBodyWeightRequestObject) (SaveBodyWeightResponseObject, error)

	// (DELETE /body-weights/{id})
	DeleteBodyWeight(ctx context.Context, request DeleteBodyWeightRequestObject) (DeleteBodyWeightResponseObject, error)
	// ListNutritionDays The user's days from from to to (both included, at most a year), each with its macros, target and workouts.
	// (GET /nutrition/days)
	ListNutritionDays(ctx context.Context, request ListNutritionDaysRequestObject) (ListNutritionDaysResponseObject, error)

	// (DELETE /nutrition/days/{date})
	DeleteDayMacros(ctx context.Context, request DeleteDayMacrosRequestObject) (DeleteDayMacrosResponseObject, error)
	// SaveDayMacros Log the macros eaten on a day, replacing the ones logged for it before.
	// (PUT /nutrition/days/{date})
	SaveDayMacros(ctx context.Context, request SaveDayMacrosRequestObject) (SaveDayMacrosResponseObject, error)
	// GetNutritionProfile The user's body for the targets; null until it was entered.
	// (GET /nutrition/profile)
	GetNutritionProfile(ctx context.Context, request GetNutritionProfileRequestObject) (GetNutritionProfileResponseObject, error)
	// SaveNutritionProfile Set the user's body, replacing it.
	// (PUT /nutrition/profile)
	SaveNutritionProfile(ctx context.Context, request SaveNutritionProfileRequestObject) (SaveNutritionProfileResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

